com.flyio.graphql#operation.query:
query addOnPlans($after: String, $before: String, $first: Int, $last: Int, $type: AddOnType) {
  addOnPlans(after: $after, before: $before, first: $first, last: $last, type: $type) {
    edges {
      cursor
      node {
        id
        name
        displayName
        description
        maxDataSize
        pricePerMonth
      }
    }
    nodes {
      id
      name
      displayName
      description
      maxDataSize
      pricePerMonth
    }
    pageInfo {
      hasNextPage
      hasPreviousPage
      startCursor
      endCursor
    }
    totalCount
  }
}

mutation deleteAddOn($input: DeleteAddOnInput!) {
  deleteAddOn(input: $input) {
    deletedAddOnName
    clientMutationId
  }
}

query agreedToProviderTos($slug: String!, $providerName: String!) {
  organization(slug: $slug) {
    agreedToProviderTos(providerName: $providerName)
  }
}
